create or replace view "puestospranger1"  ("idpuesto", "interpretacion", "interpretacion1", "interpretacion2", "interpretacion3", "nombre", "nombre1", "nombre2", "nombre3") as select puestointerpretacion.idpuesto,  interpretacion.interpretacion,  interpretacion_1.interpretacion as interpretacion1,  interpretacion_2.interpretacion as interpretacion2,  interpretacion_3.interpretacion as interpretacion3,  interpretacion.nombre,  interpretacion_1.nombre as nombre1,  interpretacion_2.nombre as nombre2,  interpretacion_3.nombre as nombre3  from (((puestointerpretacion left join interpretacion on puestointerpretacion.idinterpretacion1 = interpretacion.idinterpretacion) left join interpretacion interpretacion_1 on puestointerpretacion.idinterpretacion2 = interpretacion_1.idinterpretacion) left join interpretacion interpretacion_2 on puestointerpretacion.idinterpretacion3 = interpretacion_2.idinterpretacion) inner join interpretacion interpretacion_3 on puestointerpretacion.idinterpretacion4 = interpretacion_3.idinterpretacion where (((puestointerpretacion.idprueba)=4));/* dmap converted statement end */
